source('mp10_immune_endothelial_mechanisms_v1/scripts/common.R');plan<-rd('model_plan.tsv');st<-rd('model_status.tsv');mem<-rd('model_membership.tsv.gz');out<-list()
for(lin in c('Epi','T_lineage','Endothelial'))for(maskval in if(lin=='Epi')c('Full','M20-masked')else'Full'){
