 for(id in ids){profiles<-mem[model_id==id,profile_id];z<-a[profile_id%in%profiles,.(n_profiles=.N,mean_AUCell=mean(mean_AUCell),AUCell_sd=sd(mean_AUCell)),by=regulon];z<-merge(cov,z,by='regulon',all.x=TRUE);z[,`:=`(model_id=id,lineage=lin,mask=maskval,tested=regulon%in%tests[model_id==id,regulon])];z[,reason:=fcase(rep(st[model_id==id,status]!='completed',.N),'model_not_evaluable',n_covered_targets<5,'insufficient_regulon_targets',is.na(AUCell_sd),'profile_score_unavailable',AUCell_sd<=1e-10,'constant_AUCell',tested,'tested',default='inspect_unexpected_omission')];out[[paste(lin,maskval,id)]]<-z
 }
};z<-rbindlist(out,fill=TRUE);put(z,'scenic_model_regulon_eligibility.tsv.gz');stopifnot(!any(z$reason=='inspect_unexpected_omission'));cat('SCENIC REGULON ELIGIBILITY COMPLETE\n')
